const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    const sakurajima = ee.Geometry.Point([130.657, 31.593]);
    const startDate = '2015-05-21';
    const endDate = '2015-05-22'; // exclusive

    // 2. Data Acquisition
    const windCollection = ee.ImageCollection('ECMWF/ERA5/HOURLY')
        .filterDate(startDate, endDate)
        .filterBounds(sakurajima)
        .select(['u_component_of_wind', 'v_component_of_wind']);

    const totalSize = windCollection.size().getInfo();
    if (totalSize === 0) {
        console.log('No wind data found for the date.');
        console.log('<answer>C1</answer>');
        return;
    }

    // Split into first half (00-11 UTC) and second half (12-23 UTC)
    const firstHalf = windCollection.filter(ee.Filter.hourOfDay().lessThan(12));
    const secondHalf = windCollection.filter(ee.Filter.hourOfDay().greaterThanOrEqualTo(12));

    const firstSize = firstHalf.size().getInfo();
    const secondSize = secondHalf.size().getInfo();
    if (firstSize === 0 || secondSize === 0) {
        console.log(`First half images: ${firstSize}, Second half images: ${secondSize}`);
        console.log('<answer>C1</answer>');
        return;
    }

    // Compute mean wind components for each half
    const firstMean = firstHalf.mean();
    const secondMean = secondHalf.mean();

    const reducer = ee.Reducer.mean();
    const scale = 30000; // ERA5 nominal resolution

    const firstStats = firstMean.reduceRegion({
        reducer: reducer,
        geometry: sakurajima,
        scale: scale,
        maxPixels: 1e9
    }).getInfo();
    const secondStats = secondMean.reduceRegion({
        reducer: reducer,
        geometry: sakurajima,
        scale: scale,
        maxPixels: 1e9
    }).getInfo();

    const u1 = firstStats['u_component_of_wind'];
    const v1 = firstStats['v_component_of_wind'];
    const u2 = secondStats['u_component_of_wind'];
    const v2 = secondStats['v_component_of_wind'];

    // Check for null/undefined results
    if (u1 === null || v1 === null || u2 === null || v2 === null) {
        console.log('Wind component calculation returned null.');
        console.log('<answer>C3</answer>');
        return;
    }

    console.log(`First half (00-11 UTC): u=${u1.toFixed(2)} m/s, v=${v1.toFixed(2)} m/s`);
    console.log(`Second half (12-23 UTC): u=${u2.toFixed(2)} m/s, v=${v2.toFixed(2)} m/s`);

    // Conditions
    const firstEast = u1 > 0 && Math.abs(u1) > Math.abs(v1);
    const firstSouth = v1 < 0 && Math.abs(v1) > Math.abs(u1);
    const secondEast = u2 > 0 && Math.abs(u2) > Math.abs(v2);
    const secondSouth = v2 < 0 && Math.abs(v2) > Math.abs(u2);

    if (firstEast && secondSouth) {
        console.log('<answer>A</answer>');
    } else if (firstSouth && secondEast) {
        console.log('<answer>B</answer>');
    } else {
        console.log('<answer>C3</answer>');
    }
}

async function initEE() {
    await new Promise((resolve, reject) => {
        ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
        ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
}

initEE();
